import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Build the scene graph from the source file
const root = createScene();

// Expand InstancedMesh objects into individual Mesh objects so the
// OBJExporter (which ignores instance matrices) can export every instance.
function expandInstancedMeshes(node) {
  const replacements = [];

  node.traverse((child) => {
    if (child.isInstancedMesh) {
      const parent = child.parent;
      if (!parent) return;

      const group = new THREE.Group();
      group.name = child.name;

      const mat = child.material;
      const geo = child.geometry;
      const instanceMatrix = new THREE.Matrix4();

      for (let i = 0; i < child.count; i++) {
        child.getMatrixAt(i, instanceMatrix);
        const mesh = new THREE.Mesh(geo.clone(), mat);
        mesh.name = `${child.name}_${i}`;
        mesh.applyMatrix4(instanceMatrix);
        group.add(mesh);
      }

      replacements.push({ parent, oldChild: child, newChild: group });
    }
  });

  for (const { parent, oldChild, newChild } of replacements) {
    // Preserve the same position in the children list
    const idx = parent.children.indexOf(oldChild);
    parent.remove(oldChild);
    parent.add(newChild);
    // Move to original index
    const arr = parent.children;
    arr.splice(arr.indexOf(newChild), 1);
    arr.splice(idx, 0, newChild);
  }
}

expandInstancedMeshes(root);

// Apply a -90° X-rotation to convert from Three.js Y-up to Blender Z-up.
const rotationGroup = new THREE.Group();
rotationGroup.rotation.x = -Math.PI / 2;
rotationGroup.add(root);

// Force a full world-matrix update so all transforms are baked.
const exportScene = new THREE.Scene();
exportScene.add(rotationGroup);
exportScene.updateMatrixWorld(true);

// Export to OBJ
const exporter = new OBJExporter();
const objData = exporter.parse(exportScene);

// Write to disk
const outputDir = path.resolve('/root/output');
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}
const outputPath = path.join(outputDir, 'object.obj');
fs.writeFileSync(outputPath, objData);

console.log(`Exported OBJ to ${outputPath}`);
console.log(`File size: ${(fs.statSync(outputPath).size / 1024).toFixed(1)} KB`);

